class Solution {
    private static final long MOD = 1_000_000_007L;

    public int checkRecord(int n) {
        long[][][] dp = new long[n + 1][2][3];
        dp[0][0][0] = 1;
        for (int day = 0; day < n; day++) {
            for (int absences = 0; absences <= 1; absences++) {
                for (int lateStreak = 0; lateStreak <= 2; lateStreak++) {
                    long ways = dp[day][absences][lateStreak];
                    if (ways == 0) continue;
                    dp[day + 1][absences][0] = (dp[day + 1][absences][0] + ways) % MOD;
                    if (absences == 0) {
                        dp[day + 1][1][0] = (dp[day + 1][1][0] + ways) % MOD;
                    }
                    if (lateStreak < 2) {
                        dp[day + 1][absences][lateStreak + 1] =
                                (dp[day + 1][absences][lateStreak + 1] + ways) % MOD;
                    }
                }
            }
        }

        long answer = 0;
        for (int absences = 0; absences <= 1; absences++) {
            for (int lateStreak = 0; lateStreak <= 2; lateStreak++) {
                answer = (answer + dp[n][absences][lateStreak]) % MOD;
            }
        }
        return (int) answer;
    }
}

